func TestChangeLinesKeepsEveryLineAndEveryCell(t *testing.T) {
	long := strings.Repeat("x", 600)
	var b strings.Builder
	b.WriteString("--- f\n+++ f\n")
	for i := 1; i <= 120; i++ {
