	}
	// A wrapped error is still classified.
	wrapped := errors.Join(errors.New("context"), &fs.PathError{Op: "stat", Path: rel, Err: fs.ErrPermission})
	if got := previewFailure(rel, wrapped); got != rel+" cannot be read" {
