func changeLines(diff string) []string {
	rows := strings.Split(strings.TrimSuffix(diff, "\n"), "\n")
	if len(rows) >= 2 && strings.HasPrefix(rows[0], "--- ") {
		rows = rows[2:]
	}
	var out []string
	for _, r := range rows {
		if r == "" {
			continue
		}
		if strings.HasPrefix(r, "@@") {
			r = "  " + r
		}
		out = append(out, strings.ReplaceAll(withoutControlSpace(r), "\n", ""))
	}
	return out
}

func previewStale(modTime, scannedAt time.Time) bool {
	return !scannedAt.IsZero() && !modTime.IsZero() && modTime.After(scannedAt)
}

func previewFailure(rel string, err error) string {
	switch {
	case errors.Is(err, fs.ErrPermission):
		return rel + " cannot be read"
	case errors.Is(err, fs.ErrNotExist):
		return rel + " no longer exists"
	}
	return "the fix could not be computed — check logs"
}

func computeMisconfigFix(target string, f scan.Finding, scannedAt time.Time) MisconfigFixPreparedMsg {
	fail := func(err error) MisconfigFixPreparedMsg {
		return MisconfigFixPreparedMsg{Target: target, Rule: f.ID, Err: err}
	}
	rule, ok := remediation.FixFor(f)
	if !ok {
		return fail(errDeclined{noFixReason(f)})
	}
	rel, reason := rule.FileFor(target, f)
	if reason != "" {
		return fail(errDeclined{reason})
	}
	path, a := findingFilePath(scan.Finding{File: rel}, target, true)
	if !a.Enabled() {
		return fail(errDeclined{a.Reason})
	}
	rel = filepath.ToSlash(mustRel(target, path))
	if !staysInside(target, path) {
		return fail(errDeclined{reasonFileLinkOutsideTarget})
	}
	checks := []string{path}
	if fp, fa := findingFilePath(f, target, true); fa.Enabled() && fp != path {
		checks = append(checks, fp)
	}
	for _, p := range checks {
		info, err := os.Stat(p)
		if err != nil {
			return fail(err)
		}
		if previewStale(info.ModTime(), scannedAt) {
			return fail(errDeclined{reasonPreviewStale})
		}
	}
	original, err := readFile(path)
	if err != nil {
		return fail(err)
	}
	change, reason, err := misconfigChangeOf(rule, rel, original, f)
	if reason != "" {
		return fail(errDeclined{reason})
	}
	if err != nil {
		return fail(fmt.Errorf("%s: %w", rel, err))
	}
	file := preparedWrite{File: rel, Path: path, Original: original, Updated: change.Updated}
	if file.State, err = git.StateOf(path); err != nil {
		log.Printf("ERROR [security/misconfig] git state of %s: %v", rel, err)
		file.StateErr = true
	}
	body := rule.Title + "\n\n"
	if rule.Warning != "" {
		body += "Warning: " + rule.Warning + "\n\n"
	}
	return MisconfigFixPreparedMsg{
		Target: target, File: file, FindingFile: f.File,
		Rule: f.ID, Instance: instanceOf(f), Body: body + strings.Join(change.Lines, "\n") + "\n",
		Scope: change.Scope, Lines: change.Lines,
	}
}

func mustRel(root, path string) string {
	r, err := filepath.Rel(filepath.Clean(root), path)
	if err != nil {
		return path
	}
	return r
}
